mapper.select:
SELECT COUNT(*) FROM `register`
WHERE employee_id = #{employeeId}
  AND visit_date >= #{visitStart}
  AND visit_date < #{visitEnd}
  AND noon = #{noon}
  AND visit_state != 'CANCELLED'

mapper.insert:
INSERT INTO `register` (
    request_no, case_number, real_name, gender, card_number, birthday, age, age_type,
    home_address, visit_date, noon, department_id, employee_id, regist_level_id,
    settle_category_id, is_book, regist_method, visit_state, regist_money
) VALUES (
    #{requestNo}, #{caseNumber}, #{realName}, #{gender}, #{cardNumber}, #{birthday}, #{age}, #{ageType},
    #{homeAddress}, #{visitDate}, #{noon}, #{departmentId}, #{employeeId}, #{registrationLevelId},
    #{settlementCategoryId}, #{booked}, #{registrationMethod}, 'REGISTERED', #{registrationFee}
)

INSERT INTO charge_item (
